class stringx
{
  char* chars;
  void* my_buf;
public:
  stringx();
  stringx(const stringx&);
  stringx(const char*, int len = -1);
  ~stringx();
  const char* c_str() const { return chars; }
  friend stringx operator+(const stringx&, const stringx&);
};

class visual_rep {};
class vr_pmesh : public visual_rep {};
class vr_billboard : public visual_rep {};

enum visrep_t
{
  VISREP_PMESH,
  VISREP_BILLBOARD,
  VISREP_DROPSHADOW,
  VISREP_HIGHLIGHT = VISREP_DROPSHADOW,
  VISREP_KRMESH
};

template<class T> class instance_bank
{
public:
  T* new_instance(const stringx& filename, unsigned additional_flags);
  T* find_instance_by_filename(const stringx& filename);
};

extern instance_bank<vr_pmesh> vr_pmesh_bank;
extern instance_bank<vr_billboard> vr_billboard_bank;
visrep_t visual_rep_name_to_type(const stringx& visrep_name);
void error(const char*);

visual_rep* find_visual_rep( const stringx& visrep_name )
{
  visrep_t flavor = visual_rep_name_to_type( visrep_name );
  if ( flavor == VISREP_PMESH )
  {
    if ( vr_pmesh_bank.find_instance_by_filename( visrep_name ) )
      return vr_pmesh_bank.new_instance( visrep_name, 0 );
  }
  else
  {
    // use me when you wanna come
    if ( vr_billboard_bank.find_instance_by_filename( visrep_name ) )
      return vr_billboard_bank.new_instance( visrep_name, 0 );
  }
  stringx composite = stringx("3D Animation hasn't been loaded: ") + visrep_name;
  error( composite.c_str() );
  return 0;
}
